mapper.select:
SELECT * FROM torn_stock_monthly_state
WHERE effective_month >= #{startMonth}
  AND effective_month <= #{endMonth}
  AND state_status = 'CONFIRMED'
  AND deleted = 0
ORDER BY effective_month ASC, stocks_id ASC

SELECT s.*
FROM (
    SELECT ms.*,
           ROW_NUMBER() OVER (
               PARTITION BY ms.stocks_id
               ORDER BY ms.effective_month DESC, ms.id DESC
           ) AS row_num
    FROM torn_stock_monthly_state ms
    WHERE ms.stocks_id IN

        #{stocksId}

      AND ms.effective_month < #{targetMonth}
      AND ms.state_status = 'CONFIRMED'
      AND ms.personality_rule_version = #{personalityRuleVersion}
      AND ms.risk_rule_version = #{riskRuleVersion}
      AND ms.deleted = 0
) s
WHERE row_num = 1
ORDER BY s.stocks_id ASC

mapper.update:
UPDATE torn_stock_monthly_state ms SET stocks_shortname = source.stocks_shortname, strategy_fit_prior = source.strategy_fit_prior, maturity = source.maturity, risk_level = source.risk_level, suggested_personality = source.suggested_personality, previous_personality = source.previous_personality, metric_snapshot = source.metric_snapshot, personality_rule_version = source.personality_rule_version, risk_rule_version = source.risk_rule_version, evidence_start_time = source.evidence_start_time, evidence_end_time = source.evidence_end_time, calculated_at = source.calculated_at, update_time = CURRENT_TIMESTAMP FROM (VALUES
(CAST(#{state.id} AS BIGINT), CAST(#{state.stocksShortname} AS VARCHAR(8)), CAST(#{state.strategyFitPrior} AS VARCHAR(32)), CAST(#{state.maturity} AS VARCHAR(32)), CAST(#{state.riskLevel} AS VARCHAR(16)), CAST(#{state.suggestedPersonality} AS VARCHAR(32)), CAST(#{state.previousPersonality} AS VARCHAR(32)), CAST(#{state.metricSnapshot} AS JSONB), CAST(#{state.personalityRuleVersion} AS VARCHAR(64)), CAST(#{state.riskRuleVersion} AS VARCHAR(64)), CAST(#{state.evidenceStartTime} AS TIMESTAMP), CAST(#{state.evidenceEndTime} AS TIMESTAMP), CAST(#{state.calculatedAt} AS TIMESTAMP))
) AS source(id, stocks_shortname, strategy_fit_prior, maturity, risk_level, suggested_personality, previous_personality, metric_snapshot, personality_rule_version, risk_rule_version, evidence_start_time, evidence_end_time, calculated_at) WHERE ms.id = source.id AND ms.state_status = 'DRAFT' AND ms.manual_override = false AND ms.deleted = 0

UPDATE torn_stock_monthly_state ms SET state_status = 'CONFIRMED', confirmed_at = source.confirmed_at, confirmed_by = source.confirmed_by, update_time = CURRENT_TIMESTAMP FROM (VALUES
(CAST(#{state.id} AS BIGINT), CAST(#{state.confirmedAt} AS TIMESTAMP), CAST(#{state.confirmedBy} AS VARCHAR(64)))
) AS source(id, confirmed_at, confirmed_by) WHERE ms.id = source.id AND ms.state_status = 'DRAFT' AND ms.manual_override = false AND ms.deleted = 0
